(1040, '256772627943', '256703700565', NULL, 'We apologize for any inconveniences and frustrations caused dear', 'text', NULL, NULL, NULL, NULL, 'none', 0, NULL, 'wamid.HBgMMjU2NzAzNzAwNTY1FQIAERgSRkQ0ODNFRDY1OEI5RUI1QkExAA==', 'delivered', '2025-12-19 09:50:21', NULL, '2025-12-19 09:50:18', '2025-12-19 09:50:22', '2025-12-19 09:50:18', 'seen', 86, NULL, 0, '\n        <div class=\"rp-left\"></div>\n        <div class=\"rp-body\">\n            <div class=\"rp-title\">Replying to message</div>\n            <div class=\"rp-content\">Good morning , hope your well ,firstly apologies for the long wait we faced a few challenges with cargo planes re scheduling flights because they were opting for transporting passengers other than cargo but we are actively working on it to ensure your package is delivered as soon as possible kindly be patient with us we expect to be reaching out soon</div>\n        </div>\n        <div class=\"rp-close\"><i class=\"fa-solid fa-xmark\"></i></div>\n    ', NULL, '', NULL, 0, 1, NULL, NULL, NULL),
