(1042, '256785014553', '256772627943', NULL, 'Sent to number ending with 585', 'text', NULL, '', NULL, NULL, 'none', 0, NULL, 'wamid.HBgMMjU2Nzg1MDE0NTUzFQIAEhggQTU4NjE4NTM5QThFNkI3QzFGMkVBQzFGN0NDN0NFMzUA', 'received', NULL, NULL, '2025-12-19 09:52:14', NULL, '2025-12-19 09:52:14', 'seen', 67, NULL, 0, NULL, NULL, '', NULL, 0, 1, NULL, NULL, NULL),
