(6576, '256772627943', '256700231601', NULL, 'Kindly note that SHEIN orders normally take 2-3 weeks dear however we adjusted the time frame of the arrival of the orders to 4 weeks because of the congestion and delays at the major transportation hubs and customs clearance centers because of the festive season', 'text', NULL, NULL, NULL, NULL, 'none', 0, NULL, 'wamid.HBgMMjU2NzAwMjMxNjAxFQIAERgSRUI5MkY2NUIwQkVDRTRFMTFBAA==', 'read', '2025-12-23 21:25:39', NULL, '2025-12-23 21:24:57', '2025-12-23 21:25:44', '2025-12-23 21:24:57', 'seen', 81, NULL, 0, '<div class=\"rp-left\"></div>\n        <div class=\"rp-body\">\n            <div class=\"rp-title\">Replying to message</div>\n            <div class=\"rp-content\" href=\"#wamid.HBgMMjU2NzAwMjMxNjAxFQIAEhgUM0EyOTYxNTQ1MUJDM0JDQjUyMUYA\">You said it will take 4weeks?</div>\n        </div>\n        <div class=\"rp-close\"><i class=\"fa-solid fa-xmark\"></i></div>', NULL, '', NULL, 0, 1, NULL, NULL, NULL),
