(8415, '256772627943', '256774542581', NULL, 'Sorry for the delayed response dear, lets have a delivery guy reach out shortly', 'text', NULL, NULL, NULL, NULL, 'none', 0, NULL, 'wamid.HBgMMjU2Nzc0NTQyNTgxFQIAERgSRjZCQzVGQ0IxRjNGNkU4NjJEAA==', 'read', '2025-12-26 10:11:20', NULL, '2025-12-26 09:31:36', '2025-12-26 10:11:21', '2025-12-26 09:31:36', 'seen', 95, NULL, 0, '\n        <div class=\"rp-left\"></div>\n        <div class=\"rp-body\">\n            <div class=\"rp-title\">Replying to message</div>\n            <div class=\"rp-content\">Oh my God why aren’t you guys replying. Anyways please deliver my package tomorrow before 5pm because I’m going for a trip till 1st Jan</div>\n        </div>\n        <div class=\"rp-close\"><i class=\"fa-solid fa-xmark\"></i></div>\n    ', NULL, '', NULL, 0, 1, NULL, NULL, NULL),
