(12041, '256772627943', '256783231831', NULL, 'It\'s alright dear', 'text', NULL, NULL, NULL, NULL, 'none', 0, NULL, 'wamid.HBgMMjU2NzgzMjMxODMxFQIAERgSMDU0NDk5QTRCNkUwMEQyM0U2AA==', 'read', '2025-12-28 15:13:02', NULL, '2025-12-28 14:57:27', '2025-12-28 15:13:03', '2025-12-28 14:57:27', 'seen', 81, NULL, 0, '<div class=\"rp-left\"></div>\n        <div class=\"rp-body\">\n            <div class=\"rp-title\">Replying to message</div>\n            <div class=\"rp-content\" href=\"#wamid.HBgMMjU2NzgzMjMxODMxFQIAEhgUM0FDREY0RjlEREMyODYxODc4NTMA\">I don’t think I’m going to recieve a notification coz I’m in Kenya and I’m using safaricom so I wanted to transfer from my bank account and the registered Uganda line is off, so the money will show that it’s deducted but won’t be able to get the notification\nIt’s just you to confirm with me that you’ve received after I transfer</div>\n        </div>\n        <div class=\"rp-close\"><i class=\"fa-solid fa-xmark\"></i></div>', NULL, '', NULL, 0, 1, NULL, NULL, NULL),
