(19174, '256772627943', '256705994731', NULL, 'We are genuinely sorry about the delay in the arrival of your orders because we are experiencing delays due to the airline we are using rescheduling flights because they are opting for transporting passengers other than cargo which is affecting the delivery time \nHowever we are keeping track of your order and once it arrives we will prioritize your delivery and notify you immediately.', 'text', NULL, NULL, NULL, NULL, 'none', 0, NULL, 'wamid.HBgMMjU2NzA1OTk0NzMxFQIAERgSRDBGNUVBQTZCRTVENDk3MEM2AA==', 'read', '2026-01-01 20:49:21', NULL, '2026-01-01 13:07:43', '2026-01-01 20:49:22', '2026-01-01 13:07:43', 'seen', 81, NULL, 0, '<div class=\"rp-left\"></div>\n        <div class=\"rp-body\">\n            <div class=\"rp-title\">Replying to message</div>\n            <div class=\"rp-content\" href=\"#wamid.HBgMMjU2NzA1OTk0NzMxFQIAEhgUM0E1ODE4NEU3ODZFMTZERjFFMzUA\">Hello, how are you doing? I placed an order with Personal Shopping DxB, and the items arrived in Dubai around the 19th. I just wanted to ask when they will be in UG.</div>\n        </div>\n        <div class=\"rp-close\"><i class=\"fa-solid fa-xmark\"></i></div>', NULL, '', NULL, 0, 1, NULL, NULL, NULL),
(19175, '2348133297696', '256772627943', NULL, 'If not that the person I sent couldn\'t make it to your office last year Tuesday due to his dad that passed away, he would\'ve come to pick our phones since you people are not saying anything neither deliver it to our address. So it\'s either we come and collect it ourselves', 'text', NULL, '', NULL, NULL, 'none', 0, NULL, 'wamid.HBgNMjM0ODEzMzI5NzY5NhUCABIYIEFDQzQ0NTk1OTZCQjVGMUZDODNGOUZDNzA2QjkxOEM2AA==', 'received', NULL, NULL, '2026-01-01 13:08:08', NULL, '2026-01-01 13:08:08', 'seen', 67, NULL, 0, '', NULL, '', NULL, 0, 1, NULL, NULL, NULL),
