(26610, '256772627943', '256751293182', NULL, 'At the moment, Temu operates on a self-ordering basis. You will be provided with our Dubai address, which you will use as the delivery location when placing your order. Once the items are delivered to our Dubai address, we will handle the shipment to Uganda at a rate of UGX 35,000 per kilogram.', 'text', NULL, NULL, NULL, NULL, 'none', 0, NULL, 'wamid.HBgMMjU2NzUxMjkzMTgyFQIAERgSQzRDRjlGRDU5NkEzRDFDQTRFAA==', 'read', '2026-01-04 18:24:03', NULL, '2026-01-04 18:03:12', '2026-01-04 18:24:04', '2026-01-04 18:03:12', 'seen', 81, NULL, 0, '', NULL, '', NULL, 0, 1, NULL, NULL, NULL),
(26611, '256772627943', '256781027702', NULL, 'Kindly note that SHEIN orders normally take 2-3 weeks dear however we adjusted the time frame of the arrival of the orders to 4 weeks because of the congestion and delays at the major transportation hubs and customs clearance centers because of the festive season.', 'text', NULL, NULL, NULL, NULL, 'none', 0, NULL, 'wamid.HBgMMjU2NzgxMDI3NzAyFQIAERgSOTkzQzgzNUZBMkJDOUJDQURCAA==', 'delivered', '2026-01-04 18:16:49', NULL, '2026-01-04 18:03:37', '2026-01-04 18:16:50', '2026-01-04 18:03:37', 'seen', 81, NULL, 0, '<div class=\"rp-left\"></div>\n        <div class=\"rp-body\">\n            <div class=\"rp-title\">Replying to message</div>\n            <div class=\"rp-content\" href=\"#wamid.HBgMMjU2NzgxMDI3NzAyFQIAEhgUM0EyMzZCODYzREI3MEMxMzRDQzQA\">And how long will it take</div>\n        </div>\n        <div class=\"rp-close\"><i class=\"fa-solid fa-xmark\"></i></div>', NULL, '', NULL, 0, 1, NULL, NULL, NULL),
