(41329, '256772627943', '256708214465', NULL, 'Temu at the moment is for self ordering , you place the order on your own , and then we provide you with our dubai location for delivery and then when it gets there we ship it to uganda at a fee', 'text', NULL, NULL, NULL, NULL, 'none', 0, NULL, 'wamid.HBgMMjU2NzA4MjE0NDY1FQIAERgSRjUwNDU5MDVFQjVGRDMwMUFFAA==', 'read', '2026-01-09 07:53:48', NULL, '2026-01-09 07:47:40', '2026-01-09 07:53:49', '2026-01-09 07:47:40', 'seen', 80, NULL, 0, '<div class=\"rp-left\"></div>\n        <div class=\"rp-body\">\n            <div class=\"rp-title\">Replying to message</div>\n            <div class=\"rp-content\" href=\"#wamid.HBgMMjU2NzA4MjE0NDY1FQIAEhggQUM2MDg0MDgyODBBRkQ3M0Q3RUEzQUZGNjY2OUM5NTgA\">I\'m inquiring about Temu. Is it possible to put in orders? Was the shipping ban lifted?</div>\n        </div>\n        <div class=\"rp-close\"><i class=\"fa-solid fa-xmark\"></i></div>', NULL, '', NULL, 0, 1, NULL, NULL, NULL),
