INSERT INTO `checklist_response` (`checklist_response_id`, `date`, `user_id`, `checklist_id`, `client_id`, `value`, `narration`) VALUES
(6842, '2023-10-19 17:09:00', 50, 1, 0, 3, '1.securex ltd; the transport manager was impressed and promised business in the near future \r\n2. DHL also they have interest but need more time to look through our prices but will keep checking on them \r\n3. UGANDA BATTERIES LTD'),
(6843, '2023-10-19 17:53:55', 16, 1, 0, 3, '1. CHINA GEO Couldnot see manager Tonny because he was busy so I will prepare another day\r\n2.PAMOJA TOURS Mr. Mukiibi said that he will come to office anytime\r\n3.ADVENTURE SAFARIS They promised to bring cars for wheel balance and alignment'),
(6844, '2023-10-19 17:53:55', 16, 2, 0, 4, '1.MASH Mr. Dennis said that they are expecting the cheque this afternoon\r\n2.VITAFOAM Mr. Balaji said he signed the cheque but they expect to send it tomorrow\r\n3.ADMAN SOURCE Patrick said he already forwarded the quotation to his supervisor and he is still waiting for feedback\r\n4.KIBOKO Talked to Nudon. He requested for the pricelist and I forwarded it to him'),
(6845, '2023-10-20 16:19:18', 16, 1, 0, 3, '1.COUNTRY VIEW DRIVING SCHOOL Talked to the boss on phone because he was busy preparing tests for their clients. He asked me to leave the documents at the reception\r\n2.MASH Met Mr. Musa and he said that he is waiting for his boss to come to Uganda to authorise the tyre business\r\n3.SMART FLOORS They requested me to check on the next week'),
(6846, '2023-10-20 16:19:18', 16, 2, 0, 3, '1.VIVA Ssalongo promised to get back to me because he was so busy\r\n2.SSEWABIGA Contacted but he did not pick up\r\n3.BAMBOO ECHO TOURS Contacted but they did not pick up'),
(6847, '2023-10-20 17:09:17', 50, 1, 0, 3, 'DHL services; they rescheduled till next week \r\nHighline transporters also is promising to return to me for business \r\nSsewa transporters is still hard to bring on board. but i will keep on trying them. '),
(6848, '2023-10-20 17:09:17', 50, 2, 0, 3, 'mothercare schools they promised more orders next week \r\nkingsway schools they havent made up their minds \r\nindicar sercives '),
(6849, '2023-10-23 17:01:52', 50, 1, 0, 3, 'cipro freight had an appointment today i presented a proposal and i hope business will happen\r\n \r\nSecurex ltd also promised after reviewing and understanding the payment agreements \r\n\r\nandys garage also told me to keep in touch they will need some pieces sooner '),
(6850, '2023-10-23 17:01:52', 50, 2, 0, 2, 'movit industries the transport manager rescheduled \r\n\r\nbritam insurance also for an appointment '),
(6851, '2023-10-23 18:12:31', 16, 1, 0, 2, '1.UGANDA TODAY Talked to Martin about WA/WB and car service. He asked me to go and meet the responsible person tomorrow\r\n2.DAVIS AND SHIRTLIFF Talked to the transport officer and requested for the price quote of 265/70r16 245/70r16 195/70r14 185/70r14 195r15C 155r12'),
(6852, '2023-10-23 18:12:31', 16, 2, 0, 3, '1.COUNTRY VIEW Talked to Mr. Tamale and he promised to come office when he recovers\r\n2.SPEEDWAY ENGINEERING Contacted Mr. Matovu but his number was not available\r\n3. ROKO Talked to Mr. Bakka. He promised business of 315 this week after talking to his superior'),
(6853, '2023-10-23 18:46:13', 22, 1, 0, 3, '1. trinity express/ took the statement 2. country builders/ waiting for their promised order. 3. movit/ meet mr. banadi but he is not a easy person  '),
