(7303, '2024-02-08 17:17:02', 16, 10, 0, 4, '1400R24'),
(7304, '2024-02-08 17:32:43', 50, 1, 0, 2, '1. Ivanos logistics met with the manager and he told me about his compliant that he had presented to the company concerning quality of the tyres and he was not given any response.He further added he is okay doing business if we can maintain quality for his trucks since they travel longer distance. \r\n2. Premier distillers and Mr Avinash has no been in the country but he will reschedule a meeting and we will talk more on how to get them on board. '),
(7305, '2024-02-08 17:32:44', 50, 2, 0, 2, '1. Home pride investments called them on how to meet with the manager  so we can talk and they said they will call me tomorrow.\r\n2. Ambiance distillers to see madam stella and check on the debt recovery and they have some signed cheques but the dates are still open they will call me when dates are written onto them '),
(7306, '2024-02-09 17:41:58', 50, 1, 0, 2, '1. Ivanos logistics to deliver the order they place today of 295/80R22.5 of 4 pieces.\r\n2. Victor junior school to talk  and negotiate them on board as our new clients they have a number of vans that can consume 195R15C '),
(7307, '2024-02-09 17:41:58', 50, 3, 0, 1, '1. 295/80R22.5 of 4 pieces for IVANOS LOGISTICS  '),
(7308, '2024-02-09 17:54:51', 16, 1, 0, 1, 'KIDDAWALIME. Mr. Rukika said that he will come again to buy tyres.'),
(7309, '2024-02-12 18:08:53', 50, 2, 0, 4, '1. Gadith investments i called Mr Robert to talk on how we can continue business and he was surely willing to buy but he had been informed by the manager that we do not have the tyres he need most in stock ie 315/80R22.5 and 11R22.5. He further added that he will be in touch anytime we have stock \r\n2.Denovo bakery Mr Simon still has contact with the manager and he will schedule an appointment soon.. They have a number of rucks that can use tyres like 7.00R15 and 7.00R16 even a few of 195R15C etc \r\n3. Mr Okit of Bebeto coaches and he said he still ahs no need so far. But we will supply him once we receive stock of 315/80R22.5 \r\n4. Ivanos made a call to Mr Julius but he was not in need of any Tyres so will make more calls to get orders from him soon. '),
(7310, '2024-02-12 18:12:38', 16, 1, 0, 2, 'FULCRUM. We met Phillip with simon and he promised to give us business once thier business pops in.\r\n\r\nVIVA. Ssalongo told me to go tomorrow for some payment.'),
(7311, '2024-02-12 18:12:38', 16, 2, 0, 2, 'SPPEDWAY ENGINEERING. Contacted Matovu but the number was off.\r\nONSIGHT FARMING. The number for Mr. Nsamba was off'),
(7312, '2024-02-12 18:12:38', 16, 3, 0, 1, '3'),
(7313, '2024-02-12 18:12:38', 16, 4, 0, 1, '9.5 R17.5  3pcs\r\n8.25R16   1pc'),
(7314, '2024-02-12 18:12:38', 16, 14, 0, 2, 'SPEEDWAY\r\nONSIGHT FARMING'),
(7315, '2024-02-13 16:50:53', 50, 1, 0, 1, '1. Andys trucks to talk to Mr Andy the boss but he seemed busy and told me to talk via WhatsApp and meet this week. He is a promising client with a variety of machinery like trucks and tractors. '),
(7316, '2024-02-13 16:50:53', 50, 2, 0, 3, '1. Wonder well international school for debt recovery and Madam Rehma said that she has not yet got the money yet. But she will pay before 30 days expire.\r\n2. Ivano logistics Mr Julius said i call him tomorrow to see if he may have an order of tyres for some incoming trucks tomorrow. \r\n3. Mr Katumba of KM Investments is still not yet sure of when they will resume business fully but he said he has a few trucks moving now this month. Will visit him during the course of this week and present my proposal to him. He has trucks that need tyres of 11r22.5 and 315/80R22.5\r\n\r\n'),
(7317, '2024-02-13 18:07:59', 16, 1, 0, 5, 'TRINITY EXPRESS Mr. Boaz left me in the office\r\n\r\nVIVA The boss was not seen\r\n\r\nVITAFOAM delivered 1pc 8.25r16 MD\r\n\r\nKREM Apolo was not seen\r\n\r\nVIGO will call me'),
(7318, '2024-02-13 18:07:59', 16, 2, 0, 5, 'TRUST METAL FABRICATORS Bought 4pcs of 185r14c\r\n\r\nTRONIC asked for a quotation of 205/85r16 4pcs and 700r16 2pc. I gave them the quotation\r\n\r\nELLY Bought 2pcs of Savero 31X10.50r15\r\n\r\nBWEBALE will buy 700r16 in 3 weeks\r\n\r\nHEAVY INVESTMENTS Will get back to me\r\n\r\n');
INSERT INTO `checklist_response` (`checklist_response_id`, `date`, `user_id`, `checklist_id`, `client_id`, `value`, `narration`) VALUES
(7319, '2024-02-13 18:07:59', 16, 3, 0, 3, 'VITAFOAM UGX 3.233.200\r\n\r\nELLY SERVICE STATION UGX 1.260.000\r\n\r\nTRUST METAL FABRICATORS UGX 880.000'),
(7320, '2024-02-13 18:07:59', 16, 10, 0, 7, '1pcs Kapsen 8.25r16\r\n\r\n2pcs Savero 31X10.50r15\r\n\r\n4pcs Bearway 185r14c'),
(7321, '2024-02-13 18:07:59', 16, 20, 0, 2, 'VITAFOAM 1PC of 8.25r16\r\n\r\nELLY SERVICE STATION  2PC of 31X10.50'),
(7322, '2024-02-14 17:29:26', 50, 1, 0, 2, '1. Mothercare schools to check on the buses and vans he said need new tyres. They need 195R15C and 7.00R15 which he said he will tell m when to make a quotation.\r\n2. KM investments Mr Katumba is still promising business but still stalled and may not respond soon i may let him  take sometime to prepare business. tyres like 315/80R22.5 but still not yet stocked.'),
(7323, '2024-02-14 17:29:26', 50, 2, 0, 2, '1. Ambiance sent an order for 7.00R16 of 6 pieces but we failed to process and fullfill the order so lost business \r\n2. Ivanos logistics also sent an order of 295/80R22.5 of 2 pieces and the client cancelled it himself due to some internal issues. '),
(7324, '2024-02-14 17:35:43', 16, 1, 0, 1, 'CHINA GEO Met Mr. Ling and he requested for 1200r20 price quote\r\n\r\n'),
(7325, '2024-02-14 17:35:43', 16, 2, 0, 3, 'TRONIC Bought 2pcs of 205r16c\r\n\r\nVIVA Ssalongo said that they do not have money today but he asked me to go tomorrow\r\n\r\nONSIGHT FARMING Mr. Nsamba said that he will get back to me about 8.25r16MD '),
(7326, '2024-02-14 17:35:43', 16, 3, 0, 1, 'Tronic UGX 770.000'),
(7327, '2024-02-14 17:35:43', 16, 10, 0, 2, 'Habilead 205r16'),
(7328, '2024-02-15 16:46:57', 50, 1, 0, 1, '1. KM Investments to see and talk to Mr Katumba the boss and he was promising business so i will gt in touch with him when we bring in stock for 315/80R22.5 in a few weeks from now. He still had an issue with high price but will keep talking him through it. \r\n2. Mr Simon was not in office to visit the YY coaches but we will see him soon. '),
(7329, '2024-02-15 18:13:39', 16, 1, 0, 2, 'ASHCOM He wants 8.25r16 6pcs but he will give me updates on Monday\r\n\r\nVIVA business is low these days'),
(7330, '2024-02-16 18:07:16', 16, 1, 0, 1, 'VIVA. Paid 1million shs'),
(7331, '2024-02-16 18:07:16', 16, 2, 0, 4, 'DAFRIC LOGISTICS. Tom promised to clear balance next week when he comes to Uganda.\r\n\r\nTOUR EDDI. Contacted  the manger but he did not pick.\r\n\r\nTOM 315. Contacted Mr. Tom but he did not pick.\r\n\r\nONSIGHT FARMING. Contacted Ronny and he promised to come in the near future. he said he will need 4pcs of agriculture tractor tyres.'),
(7332, '2024-02-16 18:07:16', 16, 12, 0, 1, 'TOM315'),
(7333, '2024-02-16 18:07:16', 16, 14, 0, 3, 'VIVA \r\nDAFRIC\r\nONSIGHT FARMING'),
(7334, '2024-02-19 17:28:50', 16, 1, 0, 1, 'VIVA  Paid 1'),
(7335, '2024-02-19 17:28:50', 16, 2, 0, 6, 'KIDDAWALIME BAKERY'),
(7336, '2024-02-19 17:28:50', 16, 14, 0, 4, 'ELLY SERVICE STATION\r\nVIVA\r\nKIDDAWALIME\r\nVITAFOAM\r\n'),
(7337, '2024-02-19 17:50:27', 50, 1, 0, 1, '1. Wonderwell schools to check on more business from madam Rehema and see how far with the debt recovery \r\n'),
(7338, '2024-02-19 17:50:28', 50, 2, 0, 2, '1. mr Fortunate of TBBL to get an order and he said he will let me know by tomorrow when the trucks arrive at the yard from the journeys \r\n2. Ntake bakery called Mr Jotham and he sent us some orders but we could not fulfill all so we delivered and quoted only 9.5R17.5 H/W of 6 pieces '),
(7339, '2024-02-19 17:50:28', 50, 3, 0, 1, '1. Ntake bakery bought 6 pieces of 9.5R17.5 \r\n'),
(7340, '2024-02-19 17:50:28', 50, 4, 0, 1, '1. '),
(7341, '2024-02-20 16:11:46', 16, 1, 0, 3, 'CHINA WUYI CO. Met HR Cathy and she asked me to go back in mid arch to meet the boss.\r\n\r\nCEVA LOGISTICS. Met Budala  head transport and he referred me to Moses the workshop administrator'),
(7342, '2024-02-20 16:11:46', 16, 2, 0, 1, 'CHINA RAILWAY.  Contacted the manager and he said that the boss is out of country. But he promised to get back to me when he comes back.'),
(7343, '2024-02-20 18:12:19', 50, 1, 0, 1, '1. KM investments to have a talk with Mr Katumba the business proposal and he was not sure but he said his still not ready to make business due to some financial issues. But he is still promising and he said he will come to office for a visit here too once. \r\n'),
(7344, '2024-02-20 18:12:19', 50, 2, 0, 3, '1. Called Mr Tyson to check on him about tractor tyres and he was not sure whenhe will need them but will keep reminding him and schedule a visit to him soon. \r\n2. Called Ambiance distillers to see if they have any need as of this week but she sent in a vehicle that we fitted 4 tyres of 285/50R20. This was good and she will send more this week .\r\n3. Called Ivanos logistics but Mr Juliis was not responding yet. '),
(7345, '2024-02-20 18:12:19', 50, 3, 0, 1, '1. Ambiance distillers made a purchase of 4 tyres of size 285/50R20 '),
(7346, '2024-02-21 16:55:48', 16, 1, 0, 1, 'TRINITY EXPRESS. Met Boaz and he referred me to Mark the work shop manager. Mark asked me to call him when 315/80R22.5 is available.'),
(7347, '2024-02-21 16:55:48', 16, 2, 0, 4, 'BABY COACH. Manager bright asked me to go and meet him on Friday. He said they need 315/80R22.5 HW at 900'),
(7348, '2024-02-21 16:55:48', 16, 14, 0, 3, 'VIVA \r\nBABY COACH\r\nMASH'),
(7349, '2024-02-21 17:16:30', 50, 1, 0, 2, '1. Mr Andrew of Andys tractors we met and talked about the business proposal and he got interest so i will keep in touch and get him to visit us and see the tyres and maybe get to negotiate more about prices too. I have high hopes of bringing him on board soon. \r\n2. Victory schools in Mengo also i passed by on my way and they queried about our tyres of 315/80R22.5 and the prices of 7.00-50R16 they have many coaster buses an buses so i hope the manager will prioritize buying from us soon. '),
(7350, '2024-02-21 17:16:30', 50, 2, 0, 2, '1. Mr Fortunate of TBBL to check in for any orders but he seemed not ready according to his response. I intend to keep checking on him for business for his one of my targets \r\n2. Wonderwell schools for debt collection and any orders but she did not respond will ttry her again tomorrow. \r\n'),
(7351, '2024-02-21 17:16:30', 50, 8, 0, 1, '1. Ntake bakery paid by EFT a sum of 1'),
(7352, '2024-02-22 17:51:36', 50, 2, 0, 2, '1. Mr Gerald of mothercare schools called me asking if i can get him 195R15C at a price of 230'),
(7353, '2024-02-22 18:30:39', 16, 1, 0, 2, '1.DAFRIC LOGISTICS Tom said that his airtel money account was blocked. But he promised to sort it out today such that he can pay us\r\n\r\n2. KREM EVENTS Kamuswaga said that so he is going to give us business for truck tyres'),
(7354, '2024-02-22 18:30:39', 16, 2, 0, 4, '1.CHINA GEO Mr. Ling requested for 17.5r25 and 315/80r22.5 price quote. I am therefore waiting for his response on the quotation.\r\n\r\n2. ZINDA Paid balance of 10.000. But the tyre he took 265/70r19.5 bursted but when he came the management considered his request to pay 300000 and he took another tyre\r\n\r\n3.LANDROVER Wasswa said that they do not have any pending order for tyres\r\n\r\n4.BLUE CRANE Contacted Hilda but she did not pick. I also contacted Isaac and he promised to talk to Hilder about tyres'),
(7355, '2024-02-23 18:01:25', 50, 2, 0, 2, '1. Mr Fortunate called him to make him aware of stock of 315/80R22.5 that we have stocked today \r\n2. Mr Okit  i also informed him that we have got tyres today new stock '),
(7356, '2024-02-24 16:02:25', 16, 1, 0, 3, 'BABY COACH Bought 315/80r22.5 HW 4pcs\r\n\r\nCHINA GEO Bought 17.5r25 4pcs\r\n\r\nTRINITY Manager Mark promised to give us business soon'),
(7357, '2024-02-24 17:06:27', 50, 2, 0, 2, '1. mr fortunate made an inquiry on 275/70R222.5 but we do not have it in stock so he will call on monday \r\n2. Called Ntake but mr Jotham did not respond to my calls '),
(7358, '2024-02-26 17:46:25', 16, 1, 0, 2, 'VIVA Ssalongo ordered for 20pcs of 315/80r22.5 i.e. 14pcs MD and 6pcs HW\r\n\r\nBABY COACH Kasaija said that we deliver tommorow 2pcs 315/80r22.5 HW\r\n\r\n'),
(7359, '2024-02-26 17:46:25', 16, 2, 0, 4, 'NAMUYOMBA INVESTMENTS Tried to contact the boss but his number was off from morning\r\n\r\nKIDDAWALIME BAKERY Mr. Rukiika said that he will get back to me soon\r\n\r\nELLY SERVICE STATION Paid 1.260.000 for 31X10.5 R15 2pcs\r\n\r\nCHINA GEO Mr. Ling said that they transfered money to DFCU bank account'),
(7360, '2024-02-26 17:46:25', 16, 8, 0, 1, '1.260.000 ELLY SERVICE STATION'),
(7361, '2024-02-26 17:46:25', 16, 14, 0, 6, 'Viva\r\nNamuyomba\r\nChina Geo\r\nElly service station\r\nBaby coach\r\nKiddawalime'),
(7362, '2024-02-26 17:46:25', 16, 20, 0, 1, 'VIVA 20pcs of 315/80R22.5'),
(7363, '2024-02-26 17:46:25', 16, 124, 0, 1, 'BABY COACH 315/80R22.5 '),
(7364, '2024-02-26 18:01:04', 50, 1, 0, 2, '1. Ntake bakery to get some orders and inform them of the new stock arrival of 315/80r22.5. mr Jotham promised to send in one soon for some trucks in Mbale within a week or two.\r\n2. Ambiance distillers to get some orders but they did not have any . Madam Olivia the cashier paid some 2'),
(7365, '2024-02-26 18:01:04', 50, 2, 0, 2, '1. Mr Fortunate of TBBL called asking for 270/70R22.5 and he was expecting a different price but he said he will return to me ASAP for the order.\r\n2. KM investments but Mr Kutumba was not sure of any need for tyres for his trucks and promised to call me when they are back at the yard and after inspection of all tyres to see any need '),
(7366, '2024-02-27 17:12:01', 16, 1, 0, 3, 'BABY COACH. Bought 2 pcs of 315/80R22.5.\r\n\r\nTRINITY. Mark asked me to check on him on thursday.\r\n\r\nERAM U LTD. Peter said that its hard to change a tyre supplier.\r\n'),
(7367, '2024-02-27 17:12:01', 16, 2, 0, 3, 'CEVA. Moses said that he is still  pushing to activate seco in their system.\r\n\r\nMASH POA. Musa asked me to call Abed in keya because he is the final man in tyres.\r\n\r\nMALTESSER. Josephine asked me to buy the bid for pre qualification.'),
(7368, '2024-02-27 17:12:01', 16, 3, 0, 1, '315/80R22.5 2pcs'),
(7369, '2024-02-27 17:53:23', 50, 1, 0, 2, '1. YY coaches i got the contact of the manage form the secretary so i will try getting an appointment with him within the week or any sooner as he can avail time for me. I really hope they return on board since they were a good client from back then.\r\n2. KM investments i met Mr Ibra the transport manager and he said the trucks still have some issues but the few that are moving are still having some Tyres. But will let me know when they need some Tyres soon. '),
(7370, '2024-02-27 17:53:24', 50, 2, 0, 1, '1. Denov bakery tried calling the manager but he was not i office and said he will call back when  he makes time to talk more. He still tried to ask if we have all sizes and i told him an assurance that we do. They still seem hard to bring aboard but will do my best. '),
(7371, '2024-02-28 18:21:46', 50, 1, 0, 2, '1. Ambiance distillers went and met madam stella and we got some cheques of 10million. they will be cashed in fe weeks and get the cash balance. They gave me an order of 215/75R15 of 2 pieces and 4 pieces of 195R15C. \r\n2. Reliable engineering but the manager was busy will try them son again this week for business meeting. \r\n'),
(7372, '2024-02-28 18:21:46', 50, 2, 0, 2, '1. Denovo bakery the manager called me and told me his not in office but rescheduled and will let me know when his free so i can meet him and talk. \r\n2. Mr Fortunate also responded to my calls and told me his not yet ready to purchase any sooner due to the higher price i quoted for him. \r\n'),
(7373, '2024-02-28 18:21:46', 50, 3, 0, 2, '1. 215/75r15 4 pieces and 6 pieces of 195R15c for ambiance distillers \r\n2. Ivanos logistics also bought 295/80R22.5 2 pieces. '),
(7374, '2024-02-28 18:26:23', 16, 1, 0, 5, 'BABY COACHES delivered 2pcs of 315/80r22.5 HW\r\n\r\nDOOBA ENTERPRISES He told me to go back tomorrow\r\n\r\nVITAFOAM gave us a cheque of around 6milion\r\n\r\nDAFRIC He was not in office and when contacted he did not pick but he had told Naphtali that he is going to pay on Friday\r\n\r\nKREM EVENTS  a car is going to come soon and wear tyres'),
(7375, '2024-02-29 17:34:52', 50, 1, 0, 2, '1. YY coaches to talk to the manager but we never had time since he was leaving shortly when i arrived but i intend to make more visits to him so we can see the business future. \r\n2. Andys tractors also i met with Mr Andrew but he still has some issues with all the tractors except one forklift that he promised to buy. The tractors he needs include sixes of 25-23.5 and a few more.\r\nHe promised to buy the forklift tyres early next week if he gets the money.\r\n'),
(7376, '2024-02-29 17:34:53', 50, 2, 0, 4, '1. mr Kibedi the procurement officer of MoES to check the status of the vehicles for Busoga university and he told me they will arrive after the budget is read. But he promised to keep updating me about all this. \r\n2. Mr Fortunate called me reminding me of the order he did not buy so i will make time and see how i can visit his office and see the trucks that need tyres since his not always in office. \r\n3. Mr Lukwago of denovo bakery told me his not in kampala but will meet when his back an di intend to get him on board sooner after that if all goes well. \r\n4. mr Okit of Bebeto coaches also made some calls to him asking if he has any need yet for tyres and he siad he is still okay but will let me know incase of any need. '),
(7377, '2024-02-29 17:34:53', 50, 3, 0, 2, 'Ivanos logistics bought 2 tyres of 295/80r22.5 \r\nAmbiance distillers sent in two vehicles that took tyres of 235/60r15 4 tyres and another of 245/70r16 2 tyres '),
(7378, '2024-02-29 17:46:55', 16, 1, 0, 2, 'KINKIZI TRADERS Frank said that on Wednesday next week he is going to send a car for alignment\r\n\r\nDOOBA ENTERPRISES Met James for transport. He said that he will call me soon'),
(7379, '2024-02-29 17:46:55', 16, 2, 0, 5, 'TRUST METAL FABRICATORS Contacted Kato but he did not pick\r\n\r\nELLY SERVCE STATION Matovu said he will call me when need arises\r\n\r\nCHINA GEO Contacted Ling about payment. He sent me a proof of payment and I also forwarded it to the general manager and accounts manager\r\n\r\nBABY COACH They wanted tyres 315/80r22.5 but we did not deliver because they have a pending payment of 1.800.000. But promised to pay tomorrow\r\n\r\nFULCRUM Contacted Phillip but he did not talk because he was in the meeting but he promised to call me back'),
(7380, '2024-03-01 17:38:55', 16, 1, 0, 3, 'ZERIPEN. Met Derrick and he said they will need 9.5 R17.5. Heasked me to check on him on Friday next week.\r\n\r\nJAGUAR. Met Ambrose. He said that the boss is a  bit static when it comes to tyres but  he referred me to Geoffrey. I will meet him on monday.\r\n\r\nBABY COACH. Bought 4pcs of 315/80R22.5. And paid 1.8 for 2tyres taken before.'),
(7381, '2024-03-01 17:38:55', 16, 2, 0, 4, 'ASHCOM. Manager asked me to check on him on monday.\r\n\r\nJCRC. Mr. Ntege said that the committee will sit next week'),
(7382, '2024-03-01 17:38:56', 16, 3, 0, 1, 'RODEO 315/80R2.5 4pcs'),
(7383, '2024-03-01 17:38:56', 16, 4, 0, 1, 'RODEO 315/80R2.5 4pcs'),
(7384, '2024-03-01 17:38:56', 16, 10, 0, 4, 'RODEO 315/80R2.5 4pcs'),
(7385, '2024-03-01 17:38:56', 16, 20, 0, 1, 'RODEO 315/80R2.5 4pcs'),
(7386, '2024-03-01 17:39:02', 50, 1, 0, 2, '1. YY COACHES  the manager informed me when we met at his office that we can not  meet in his office premises so will schedule a meeting with him outside office next week on Tuesday. \r\n2. KM INVESTMENTS  Mr Katumba was still inquisitive of our tyre quality and i guaranteed him the best quality fir 12r22.5 and 31/80r22.5 and he saw some pictures of the tread designs though he has a different type of tread he describes as all Position so i will have to convince him about this. But as of now his still a promising client i can abate to'),
(7387, '2024-03-01 17:39:03', 50, 2, 0, 3, '1. Mr Lukwago of DENOVO  bakery told me we can meet on Monday at his office and talk about the business proposal and how we can revive business with them again. \r\n2.Mr Ivan of MILDMAY also promised me a meeting on Monday at his office in sseguku. He intends to find out more from me about the tyres for 235/75r17 and make negotiations in pricing too. \r\n3. Mr Gerald of MOTHERCARE schools also said he has a new van that needs tyres of 195R15. will keep in touch to make the order happen since he last bought last year in November from us. '),
(7388, '2024-03-04 17:20:11', 16, 1, 0, 4, 'DAFRIC. I met Tom and he promised to pay today.\r\n\r\nJAGUAR. Met Ambrose and Geoffrey. Geoffrey approved 315/80R22.5 and he said he will give me feedback after presenting it to the director.\r\n\r\nSDB . Met the administrator and he asked me to go back on Thursday and meet the boss.\r\n\r\nVIVA. Paid 5m via bank.'),
(7389, '2024-03-04 17:20:12', 16, 2, 0, 3, 'BWEBALE. Bought 2pcs of 195/65R15.\r\nBABY COACH. Contacted Kasaija but he did not pick. I will try him tomorrow.\r\nASHCOM. The manager promised to give me feedback after seeing the boss about8.25R16.\r\n'),
(7390, '2024-03-04 17:20:12', 16, 3, 0, 1, '195/65R15. 2pcs'),
(7391, '2024-03-04 17:20:12', 16, 4, 0, 1, '195/65R15. 2pcs'),
(7392, '2024-03-04 17:20:12', 16, 8, 0, 2, '5'),
(7393, '2024-03-04 17:20:12', 16, 10, 0, 2, '195/65R15.'),
(7394, '2024-03-04 17:20:12', 16, 14, 0, 2, 'BABY COACH\r\nBWEBALE'),
(7395, '2024-03-04 17:25:57', 50, 1, 0, 2, 'DENOVO BAKERY called Mr Lukwago and he promised to meet because he was not in office and gave me the number of Mr Mukasa his transport technician. He made some inquiries and discussed on prices so i hope for business soon. \r\nNTAKE BAKERY  met Mr Jotham and he said he will give me an order within this week soon for some truck tyres. '),
(7396, '2024-03-04 17:25:57', 50, 2, 0, 2, '1. TBBL called them for an order but the manager said he had no need soon So will keep in touch with them too.\r\n2. Mr Kibedi of MoES still insists we reduce the price for him so will make him to buy the real price. He wants 315/80R22.5 but his still not forthcoming.\r\n'),
(7397, '2024-03-05 17:55:41', 50, 1, 0, 4, '1. TRAIN UP A CHILD SCHOOL  met the transport manager Mr Katongole and he was promising for business as long as we can guarantee him good service. He even wanted commission from his purchases which we negotiated and he promised business on Monday if all goes well on his side. He has over 15 vans and 19 coaster buses which can use tyres like 195r15c and 215/70R15 and 7.00R15.\r\n2. DENOVO BAKERY  met with Mr Lukwago but he was going for a medical leave so he can resume work after medication but his still a good prospect to bring on board.\r\n3.AMBIANCE DISTILLERS they are still not having any need for tyres and i hope they buy soon being one of our big players. \r\n4.ELIANA SCHOOLS the headteacher Mr Paul was not happy with our prices but he said if they are negotiable he will be forthcoming '),
(7398, '2024-03-05 17:55:42', 50, 4, 0, 1, '1. IVANOS LOGISTICS  they ordered for 295/80R22.5 but not yet his still not sure because they still want to make payments of debts to zero balance. '),
(7399, '2024-03-05 18:13:27', 16, 1, 0, 2, 'DAFRIC LOGISTICS Paid and cleared the balance of 1.405.000\r\n\r\nTRAIN UP CHILD SEETA Met the manager for Najjanankumbi and Bugoloobi branches who is under Atwine account. He gave me the number for musiraamu the transport manager for Seeta and Wakiso branches when I contacted him. He promised to get back to me in the evening'),
(7400, '2024-03-05 18:13:27', 16, 2, 0, 4, 'TAHFEEZ TOURS Contacted Ibra He said that he will get back to me after the meeting\r\n\r\nBABY COACH Contacted Kasaija but he did not pick\r\n\r\nZINDA Mr. Swaibu promised to come for some tyres soon\r\n\r\nADMAN SOURCE Contacted Patric but he didnot pick\r\n\r\n'),
(7401, '2024-03-06 16:16:42', 16, 1, 0, 2, 'GANATRA. Gabriel promised to come for more business discussion.\r\n\r\nNAMUKUPA. Met Haji and he referred me to Badiru. Badiru promised to come tomorrow.'),
(7402, '2024-03-06 16:16:43', 16, 2, 0, 4, 'NAMUYOMBA. Bashir promised to take 11R next week on tuesday.\r\n\r\nKINKIIZI. We did not talk to Frank because he was busy.\r\n\r\nBABY COACH. Tried to contact Kasaija but he did not pick.\r\n\r\nFULCRUM. I tried to convince Phillip but he plays it hard . On this note'),
(7403, '2024-03-06 17:43:15', 50, 1, 0, 3, '1. YY COACHES met with Mr Ogwang and he gave me some ideas and complaints on the issues they faced with our batch we supplied them a while ago but he said he will give me time tomorrow to negotiate more. he is still promising to buy from us i hope to bring him on board. \r\n2. BEBETO COACHES  met with Mr okit but seemed still okay with what he has on his vehicles though he will send in an order soon. He was worried if the prices increased but they seem the same since when last bought and will buy am sure. \r\n3. NTAKE BAKERY  the procurement officer Mr Jotham was not in office he had a two days leave from work but he said once his back at work he will check through and send in an order if there is any.'),
(7404, '2024-03-06 17:43:15', 50, 2, 0, 2, '1. ELIANA JUNIOR SCHOOLS the headteacher  said he lost contact with the contact person from our company that was Mwanjuzi but he will meet me tomorrow and we will discuss on how to get them back on board they area very promising prospect buyer\r\n2. ROBERVINE  called Mr Robert but he was still promising to buy and said he will come to office tomorrow to talk of the debt he has and buy some tyres. \r\n'),
(7405, '2024-03-07 16:55:49', 50, 1, 0, 3, 'ELIANA JUNIOR SCHOOL  they had query about the debt message they have been getting recently but i made clarification to that. Thye still wanted to do business with us and promised to buy from us so will keep talking to them and get orders incase of any. \r\nYY COACHES  the manager Mr. Oketch said he need smore time thinking about it and see if he will do business with us because his supplier has been not bad. I personally told him we will serve them and give them quality and explained about the old batch we sold to them and why it turned out that bad. \r\nHOME PRIDE INVESTMENTS  the procurement officer happened to not be in office due to some circumstances but we shared contacts with his office so i can comeback  and meet him. They were a good account and will work on seeing them back '),
(7406, '2024-03-07 16:55:49', 50, 2, 0, 3, 'KM INESTMENTS  Mr Ibra seems to not be sure of how he will convince his boss to do business with us because he seems still okay and battling a debt with his old supplier. \r\nNTAKE BAKERY he promised an order though not yet any now and his still checking on all the fleet hope for one soon \r\nAMBIANCE DISTILLERS they also had no order though she asked for the price of 215/75R15 and i told her but no response as of today.'),
(7407, '2024-03-07 18:04:21', 16, 1, 0, 3, 'TRINITY Manager Mark was not seen because he had gone to Buwama to sort issues on the bus that caught fire. He promised to get back to me as soon as he comes back\r\n\r\nBABY COACH Mr. Kasaija did not pick But it is found that he just rejects my calls intentionally because of the following\r\nThey feel their personal interests are not catered for like commission\r\nThey say that not all the time we deliver that they have cash. Sometimes they need to be given a few days to pay\r\nThey say that our tyres are expensive because they have another supplier who gives them 315/80r22.5 at 860.000\r\n\r\nVITAFOAM Mr. Balaji promised to pay soon'),
(7408, '2024-03-07 18:04:21', 16, 2, 0, 2, 'YOKUKU Manager Akera asked me to meet him next week on Wednesday\r\n\r\nTUJJE SAFARIS Mr. Kirunda is still in the feild but he asked me to check on him on 15/3/2024'),
(7409, '2024-03-08 18:01:13', 50, 2, 0, 2, 'TBBL  called Mr fortunate to get some orders and remind him of the recent order he did not respond too. He still has some issues with the trucks that he wanted to buy the tyres for but will respond soon he promised. \r\nAMBIANCE DISTILLERS the response was delayed but she promised to get back to me incase she ahs some need for tyres she expects 2 vehicles from Masaka this weekend. '),
(7410, '2024-03-08 18:35:33', 16, 1, 0, 3, 'BABY COACH. Bought 2 pcs of 315/80R22.5\r\n\r\nZERIPEN. I did not see Derrick  at office'),
(7411, '2024-03-08 18:35:33', 16, 2, 0, 3, 'VIVA. Ssalongo promised to get back to me.\r\n\r\nDEWIL INVESTMENTS LTD. Matovu said that need 10.00R20 12pcs on monday and he promised to pay in a week.\r\n\r\nDAFRIC LOGISTICS. Sharon promised an order for 205R16 2Ppcs.\r\n\r\n'),
