(7413, '2024-03-08 18:35:33', 16, 4, 0, 1, '315/80R22.5 2pcs'),
(7414, '2024-03-08 18:35:33', 16, 10, 0, 2, '315/80R22.5 2pcs'),
(7415, '2024-03-08 18:35:33', 16, 14, 0, 2, 'VIVA\r\n\r\n\r\nDAFRIC'),
