(7965, '2024-10-11 16:02:01', 60, 1, 0, 2, 'KYELIMA HARDWARE.Bought 2 pieces of 700R16\r\nLUUKA PLASTICS.Has promised an order next week.\r\n,60'),
(7966, '2024-10-11 18:07:54', 16, 1, 0, 5, 'KINKIZI TRADERS Cleared their balances\r\n\r\nERRIMAT INDUSTRIES Raymond asked me to go back on Monday for 315/80r22.5 business\r\n\r\nKREM EVENTS Bought 4pcs of 195r15c Bearway\r\n\r\nJCRC Perezi promised to process payment soon\r\n\r\nDEPENDABLE OUTCOMES Manager Kam asked me to check on him after two weeks from now ie 28/10/24\r\n\r\n,16'),
(7967, '2024-10-14 16:44:07', 60, 1, 0, 4, 'EAST AFRICA ROOFINGS. The procurement officer requested me to quote for him 265/70R19.5 and they promised me to give me business.\r\nMOVIT. They told me to send them an Email about our company and the products we offer.\r\nTRIPPLE S TYRES. Wanted 185/65R15 but we dont have it in stock.\r\nWILKEN PROPERTIES.I will send them an email tomorrow.,60'),
(7968, '2024-10-14 18:00:29', 16, 1, 0, 4, 'ERRIMAT INDUSTRIES Raymond asked me to go there tomorrow after sorting their finances to see how many cars need tyres\r\n\r\nKREM EVENTS Herman told me by the end of this week he will have paid some money because there is need of  tyres\r\n\r\nBABY COACH I did not see manager Bright but i will go there again\r\n\r\nKIDDAWALIME Mr Rukiga told me at the moment he does not have money to buy tyres\r\n,16'),
(7969, '2024-10-15 17:45:49', 16, 1, 0, 4, 'MAGANJO GRAIN MILLERS. Met Yiga and Tonny. They accepted to give us business of 315. 80R22.5. Tonny said that they can buy it at 990.000 with VAT inclusive.\r\n\r\nERRIMAT INDUSTRIES. I did not meet with Reymond because he got an urgent meeting, but I must see him very soon since they are near our Office.\r\n\r\nKREM EVENTS.  Apolo is still in village, but he promised to come on Thursday.\r\n\r\nADVENTURE VOCATIONAL SAFARIS. The director was not there. I will go back very soon.,16'),
(7970, '2024-10-15 17:56:02', 60, 1, 0, 4, 'MUTIMA MATTRESSES.Has promised me an order soon.\r\nRHINO FUNERAL SERVICES.They have also promised me to order soon.\r\nMULOWOOZA CONSTRUCTION.They still need some time they are re-establishing the company.\r\nMBS FRUIT AGENCIES.The manager showed a positive reply and am hoping they will come back and buy from us.\r\n,60');
INSERT INTO `checklist_response` (`checklist_response_id`, `date`, `user_id`, `checklist_id`, `client_id`, `value`, `narration`) VALUES
(7971, '2024-10-15 16:07:27', 60, 1, 0, 3, 'SGA SECURITY.Am still pushing but the transport manager has told me she is yet to put in a requistion so i hope to get an order from them soon.\r\nULTIMATE SECURITY. The procurement manager has said they are still fine but incase of any need he will call me.\r\nNATIONAL ENTERPRISES COMPANY.The manager has told me i meet him next week with the company profile and a catalogue.,60'),
(7972, '2024-10-16 18:48:35', 2, 4, 0, 4, '5466ghfhfhhfbf'),
(7973, '2024-10-16 18:48:35', 2, 4, 0, 4, 'saddsfsdfdsfa'),
(7974, '2024-10-17 16:54:10', 16, 1, 0, 4, 'JCRC Paul promised business of 265/75r16 4pcs soon but he is requesting for his added commission\n\nKREM EVENTS Apolo promised to pay tomorrow\n\nERRIMAT Raymond asked some time to organize requisitions and promised to get back to me as soon as they are ready\n\nMAGANJO GRAIN MILLERS Talked to Yiga. He promised to send all sizes they use for quotation'),
(8028, '2024-10-18 17:16:30', 60, 1, 0, 5, 'KYELIMA HARDWARE.Mr.Fred promised me an order for 315/80R22.5 soon.\nADMAN SOURCE.The manager promised me business i will keep on checking on them.\nFUFA UGANDA.The procurement wants some commission before he adds me to the list of suppliers because they want 315/80R22.5 for their buses\nYY COACHES.The director promised to give me an order incase he needs i will check on him back next week\nFLY EXPRESS.Jamal sid he still has tyres but tomorrow he will come for alignment'),
(8029, '2024-10-18 18:05:13', 16, 1, 0, 4, 'AFRICAN QUEEN I did not find him there but he told me to call him on Monday to give me an appointment\n\nAZAM MILLERS I spoke with manager Isa and he told me to call him next week on Friday\n\nCEVA LOGISTICS I did not see Mr. Moses but i will plan again a meeting with him \n\nKREM EVENTS I found Mr. Apollo and he told me to go back tomorrow to get the money\n\n'),
(8030, '2024-10-18 18:05:13', 16, 2, 0, 1, 'CHEAP HARDWARE Asun said he will deposit money on my mobile today evening'),
(8031, '2024-10-19 16:00:24', 16, 1, 0, 0, 'KREM EVENTS Cleared its debt'),
(8032, '2024-10-19 16:00:24', 16, 1, 0, 0, 'KREM EVENTS Cleared its debt'),
(8033, '2024-10-22 17:08:33', 60, 1, 0, 4, 'GRAPHIC SYSTEMS.I was following up on the quotation i sent to them for 185R14C but the procurement officer said she will get back to me.\nTRANSPAPER.The manager told me business is not running well they have few orders for their products and he has said i check him back next month.\nREGAL PAINTS. The procurement officer said I check on him next month in November for now he has no requisitions.\nLUUKA PLASTICS.I picked the cheque for the Tyres we supplied them on Saturday.'),
(8034, '2024-10-22 17:08:33', 60, 2, 0, 2, 'FAMILY LOAF.I called the transport manager and said i meet him tomorrow at the office.\nEUROFORM.The operations officer told me he is in leave i check on him a week from now.'),
(8035, '2024-10-22 17:08:33', 60, 122, 0, 1, 'SABA GIFCO.They requested for a quotation of 315/80R22.5 and 385/65R22.5 but the lady said our price is still high she also said we talk about the guarantee and she said when they are to buy they will buy more than30 pieces.'),
(8036, '2024-10-23 17:30:06', 60, 1, 0, 2, 'RHINO FUNERAL SERVICES.Promised to give me an order.\nFAMILY LOAF.The manager also promised to give me business'),
(8037, '2024-10-23 17:33:42', 16, 1, 0, 0, 'Vitafoam bought 8pcs of 9.5\n\nTrinity bought 3pcs of 315 HW\n\nPIN TRAVEL Bought 2 pcs of 235/85R16'),
(8038, '2024-10-24 16:46:15', 16, 1, 0, 2, 'TBBL Met Justine the procurement manager. He promised business of 315/80r22.5 and 12r22.5\n\nMAGANJO Met Tonny. we agreed on prices and sent them the price quote'),
(8039, '2024-10-24 16:46:15', 16, 2, 0, 1, 'JCRC They bought 4pcs of 265/75r15'),
(8040, '2024-10-24 16:46:15', 16, 9, 0, 2, 'Gayaza Road\n\nMaganjo Road'),
(8041, '2024-10-24 17:28:35', 60, 1, 0, 3, 'LUUKA PLASTICS.Has promised me an order.\nKYELIMA HARDWARE.I didnt find the transport officer will go back tomorrow\nKITENDE MODERN.They have promised business.'),
(8042, '2024-10-24 17:28:35', 60, 4, 0, 1, 'IVANOS.Ordered for 315/80R22.5 14 pieces.'),
(8043, '2024-10-25 17:58:34', 16, 1, 0, 1, 'PIN TRAVEL .Mr kavulu requested for 265/70R17 price quote'),
