INSERT INTO `task` (`task_id`, `title`, `description`, `status`, `priority`, `user_id`, `due_date`, `created_at`, `updated_at`, `start_date`, `completion_comment`, `created_by`) VALUES
(1, 'Reconcile June bank statement', 'Match all transactions against the bank statement for June and flag any discrepancies.', 'in_progress', 'high', 2, '2026-05-28', '2026-05-26 23:22:07', '2026-06-10 23:09:08', NULL, NULL, NULL),
(2, 'Follow up on overdue invoices', 'Call clients with invoices past due date and record responses in the system.', 'in_progress', 'urgent', 2, '2026-05-26', '2026-05-26 23:22:07', '2026-05-26 23:22:07', NULL, NULL, NULL),
(3, 'Update stock reorder points', 'Review current restock levels for all items and adjust based on last 3 months movement.', 'completed', 'medium', 2, '2026-05-31', '2026-05-26 23:22:07', '2026-06-10 23:09:39', NULL, 'errerett', NULL),
(4, 'Prepare monthly sales report', 'Compile sales figures by shop and salesperson for management review.', 'in_progress', 'high', 2, '2026-05-27', '2026-05-26 23:22:07', '2026-06-10 23:09:04', NULL, NULL, NULL),
(5, 'Onboard new supplier — Kampala Tyres', 'Collect TIN, bank details, and signed supply agreement. Add to system.', 'completed', 'medium', 2, '2026-05-24', '2026-05-26 23:22:07', '2026-05-26 23:22:07', NULL, NULL, NULL),
(6, 'Train cashiers on new receipt flow', 'Walk through the updated receipt process with all shop cashiers.', 'in_progress', 'medium', 9, '2026-05-29', '2026-05-26 23:22:07', '2026-05-26 23:22:07', NULL, NULL, NULL),
(7, 'Audit warehouse stock — Ntinda store', 'Physical count of all items in Ntinda. Compare against system balance.', 'completed', 'urgent', 2, '2026-05-25', '2026-05-26 23:22:07', '2026-06-10 23:09:20', NULL, 'rtrtytry', NULL),
(8, 'Review purchase orders Q2', 'Check all Q2 POs for pricing discrepancies and unapproved variations.', 'pending', 'low', 21, '2026-06-02', '2026-05-26 23:22:07', '2026-05-26 23:22:07', NULL, NULL, NULL),
(9, 'Set up company targets for July', 'Enter monthly and quarterly targets per shop and department.', 'pending', 'high', 1, '2026-05-30', '2026-05-26 23:22:07', '2026-05-26 23:22:07', NULL, NULL, NULL),
(10, 'Clear pending requisitions', 'Approve or reject all requisitions sitting in pending state for more than 5 days.', 'completed', 'medium', 2, '2026-05-23', '2026-05-26 23:22:07', '2026-05-26 23:22:07', NULL, NULL, NULL),
(11, 'Fix attendance import errors', 'Three employees showing no clock-in records. Verify ZKTeco sync.', 'in_progress', 'urgent', 2, '2026-05-26', '2026-05-26 23:22:07', '2026-05-26 23:22:07', NULL, NULL, NULL),
(12, 'Send client statements — end of month', 'Email outstanding statements to all clients with balances over UGX 500,000.', 'pending', 'medium', 23, '2026-06-01', '2026-05-26 23:22:07', '2026-05-26 23:22:07', NULL, NULL, NULL);
